import{_ as t,c as a,o,ae as d}from"./chunks/framework.Cd-3tpCq.js";const g=JSON.parse('{"title":"Tax Rates","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/settings/tax-rates/index.md","filePath":"api/graphql-api/admin/settings/tax-rates/index.md"}'),r={name:"api/graphql-api/admin/settings/tax-rates/index.md"};function i(s,e,n,c,l,h){return o(),a("div",null,e[0]||(e[0]=[d('<h1 id="tax-rates" tabindex="-1">Tax Rates <a class="header-anchor" href="#tax-rates" aria-label="Permalink to &quot;Tax Rates&quot;">​</a></h1><p>The Tax Rates menu is the store-wide list of tax rates and the actions you can take on them. It mirrors the admin <strong>Settings → Taxes → Tax Rates</strong> screen.</p><h2 id="what-a-tax-rate-is" tabindex="-1">What a tax rate is <a class="header-anchor" href="#what-a-tax-rate-is" aria-label="Permalink to &quot;What a tax rate is&quot;">​</a></h2><p>A <strong>tax rate</strong> is a single rule that defines the tax <strong>percentage</strong> for a location. Each rate targets a <code>country</code> (and optionally a <code>state</code>) plus a zip — either a <strong>single</strong> zip code or a zip-code <strong>range</strong>. On its own a rate does nothing to a product; rates are grouped into <strong>Tax Categories</strong>, and a tax category is then assigned to a product. At checkout, the rate whose location matches the customer&#39;s address determines the tax applied.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>identifier</code></td><td>A unique label for the rate.</td></tr><tr><td><code>isZip</code></td><td><code>true</code> = the rate targets a <strong>zip range</strong> (<code>zipFrom</code>–<code>zipTo</code>); <code>false</code> = it targets a <strong>single</strong> <code>zipCode</code>.</td></tr><tr><td><code>zipCode</code></td><td>The single zip code, set only when <code>isZip</code> is <code>false</code>.</td></tr><tr><td><code>zipFrom</code> / <code>zipTo</code></td><td>The start/end of the zip range, set only when <code>isZip</code> is <code>true</code>.</td></tr><tr><td><code>state</code> / <code>country</code></td><td>The location the rate applies to. <code>country</code> is a two-letter ISO code.</td></tr><tr><td><code>taxRate</code></td><td>The tax <strong>percentage</strong> (a number from 0 to 100).</td></tr></tbody></table><h2 id="conditional-zip-rules" tabindex="-1">Conditional zip rules <a class="header-anchor" href="#conditional-zip-rules" aria-label="Permalink to &quot;Conditional zip rules&quot;">​</a></h2><p>When you <strong>create</strong> or <strong>update</strong> a rate, the zip fields you must supply depend on <code>isZip</code>:</p><table tabindex="0"><thead><tr><th><code>isZip</code></th><th>Required zip fields</th><th>Targets</th></tr></thead><tbody><tr><td><code>false</code></td><td><code>zipCode</code></td><td>A single zip code</td></tr><tr><td><code>true</code></td><td><code>zipFrom</code> <strong>and</strong> <code>zipTo</code></td><td>A zip-code range</td></tr></tbody></table><p>Supplying <code>isZip: true</code> without <code>zipFrom</code>/<code>zipTo</code>, or <code>isZip: false</code> without <code>zipCode</code>, is rejected with a validation error. On update the rule is re-checked after your change is merged onto the existing rate — so if you flip <code>isZip</code> you must also send the matching zip field(s) in the same request.</p><h2 id="create-update-delete" tabindex="-1">Create, update, delete <a class="header-anchor" href="#create-update-delete" aria-label="Permalink to &quot;Create, update, delete&quot;">​</a></h2><ul><li><strong>Create</strong> adds a new rate. <code>identifier</code> must be unique, <code>country</code> is a two-letter ISO code, and <code>taxRate</code> is 0–100.</li><li><strong>Update</strong> is partial — send only the fields you want to change; omitted fields keep their current value. The conditional zip rules above are re-validated.</li><li><strong>Delete</strong> removes the rate permanently. Any tax categories that referenced it keep working; only the rate itself is removed.</li></ul><p>There is <strong>no mass-delete</strong> and <strong>no export</strong> for tax rates over GraphQL — rates are deleted one at a time.</p><h2 id="relationship-to-tax-categories" tabindex="-1">Relationship to Tax Categories <a class="header-anchor" href="#relationship-to-tax-categories" aria-label="Permalink to &quot;Relationship to Tax Categories&quot;">​</a></h2><p>Tax rates are the building blocks of <strong>Tax Categories</strong>. A tax category bundles one or more tax rates together; products are assigned a tax category, not individual rates. To change which rates a product taxes by, edit its tax category&#39;s rate list — see the <a href="/api/graphql-api/admin/settings/tax-categories/">Tax Categories</a> menu.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="./list.html">List tax rates</a></td><td><code>adminSettingsTaxRates</code> query</td></tr><tr><td><a href="./detail.html">Get a single tax rate</a></td><td><code>adminSettingsTaxRate(id:)</code> query</td></tr><tr><td><a href="./create.html">Create a tax rate</a></td><td><code>createAdminSettingsTaxRate</code> mutation</td></tr><tr><td><a href="./update.html">Update a tax rate</a></td><td><code>updateAdminSettingsTaxRate</code> mutation</td></tr><tr><td><a href="./delete.html">Delete a tax rate</a></td><td><code>deleteAdminSettingsTaxRate</code> mutation</td></tr></tbody></table><p>Permissions: <code>settings.taxes.tax_rates.create</code> / <code>.edit</code> / <code>.delete</code>.</p><p>All operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',19)]))}const u=t(r,[["render",i]]);export{g as __pageData,u as default};
